/**
 * Девять состояний из thinking-orbs — каждое отдельная ручная анимация:
 * - `working`    — частицы на наклонённых орбитах
 * - `searching`  — меридиан сканирования бежит по точечному глобусу
 * - `solving`    — полосы перемешиваются четвертями и защёлкиваются назад
 * - `listening`  — волна катится по кольцам широт
 * - `connecting` — созвездие само себя разводит, по рёбрам бегут пакеты
 * - `weaving`    — три пряди заплетаются вокруг сферы
 * - `composing`  — колышущаяся многополосная лента
 * - `breathing`  — кольцо анфас, медленно меняющее форму
 * - `shaping`    — точечный контур: круг → треугольник → квадрат
 */
export type OrbState =
  | 'working'
  | 'searching'
  | 'solving'
  | 'listening'
  | 'connecting'
  | 'weaving'
  | 'composing'
  | 'breathing'
  | 'shaping';

/**
 * Размер в логических пикселях. Тюнингов ровно два: 64 (аватар) и 20
 * (инлайн в строке текста). Это разные дизайны, а не масштаб одного —
 * у каждого свои количество точек, их радиус и скорость.
 */
export type OrbSize = 64 | 20;
